INSERT INTO "protocols" ("protocol_id", "name", "version", "domain", "steps_json", "source_id", "url") VALUES
('kanagawa_river_citizen_survey__manual', '県民参加型調査 調査マニュアル（神奈川県環境科学センター）', NULL, '河川モニタリング(水質・底生動物・魚類・植物・両生類・鳥類 総合)', '[{"step": 1, "title": "調査の計画を立てる", "description": "何を調べたいか（水質・底生動物・魚類・植物・両生類・鳥類）と、いつ・どこで調査するかを決める。分類群ごとに適期・適地が異なる（底生動物は8〜9月/12〜1月、魚類は初夏〜秋、植物は春と秋が適期、と本文に記載）。"}, {"step": 2, "title": "調査に必要な手続きを行う", "description": "底生動物・魚類を調査する場合は事前に特別採捕許可の登録が必要（環境科学センターが手続き）。調査の1週間前までに調査日時・場所・使用する漁具を事務局へ連絡する。投網利用時や多人数実施時はのぼり旗を掲げる。"}, {"step": 3, "title": "調査に必要な道具を用意する", "description": "分類群別に必要な道具が本文に列挙されている：底生動物＝濡れてよい服・長靴・タモ網・バケツ・白色バット・ピンセット・ルーペ・サンプル瓶・固定液(エタノール)／魚類＝同左＋観察用アクリル水槽／植物＝ビニール袋・剪定ばさみ・新聞紙／水質＝温度計・pHメーター／共通＝調査シート・筆記用具・カメラ・調査マニュアル・図鑑・のぼり旗・救急箱・緊急連絡先。下線付きの道具は貸出可。"}, {"step": 4, "title": "現地調査をする", "description": "共通シート(表)にまず調査日時・場所・水質の状況を記録する。水質は水質ランク(人の五感)・気温(温度計、直射日光を避けて測定)・水温(温度計、採水後直ちに測定)・pH(pHメーター)を測定する。分類群ごとの採集・観察方法が本文に定められている（底生動物＝タモ網で1分間×3箇所採取、魚類＝投網、植物＝踏査）。"}, {"step": 5, "title": "標本を作成する（必要な場合）", "description": "底生動物・魚類は現地で名前が分からない個体をアルコール(70〜80%)で固定・保存し、採集ラベル・同定ラベルを付す（ホルマリンは劇物のため使用しない）。植物は新聞紙に挟んで乾燥させる。"}, {"step": 6, "title": "同定する", "description": "調査シート・図鑑・顕微鏡等を用いて種を同定する。名前が分からない場合は写真・標本を事務局に送り、専門家に同定してもらうことができる。"}, {"step": 7, "title": "記録・報告する", "description": "共通シート・現地調査シート・結果シートの3種に記録する。共通シート・結果シートは電子メールまたは郵送で事務局へ提出する。調査期間後の提出分は次年度の調査結果として扱われる（本文注記）。"}]', 'kanagawa_river_citizen_survey', 'https://www.pref.kanagawa.jp/documents/3188/manyual.pdf');
